16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
67	    private Set<Pet> pets;
68	
69	    /**
70	     * Default the registration date to the server's current date when none was
71	     * supplied at creation time.
72	     */
73	    @PrePersist
74	    private void defaultRegistrationDate() {
75	        if (this.registrationDate == null) {
76	            this.registrationDate = LocalDate.now();
77	        }
78	    }
79	
80	    public String getAddress() {
81	        return this.address;
82	    }
83	
84	    public void setAddress(String address) {
85	        this.address = address;
86	    }
87	
88	    public String getCity() {
89	        return this.city;
90	    }
91	
92	    public void setCity(String city) {
93	        this.city = city;
94	    }
95	
96	    /**
97	     * The owner's locality: the canonical region derived from its {@link #city}
98	     * via the fixed {@link CityRegion} table, or {@code "UNKNOWN"} when the city
99	     * is not in the table.
100	     */
101	    public String getLocality() {
102	        return CityRegion.regionFor(this.city);
103	    }
104	
105	    public String getTelephone() {
106	        return this.telephone;
107	    }
108	
109	    public void setTelephone(String telephone) {
110	        this.telephone = telephone;
111	    }
112	
113	    public String getEmail() {
114	        return this.email;
115	    }
116	
117	    public void setEmail(String email) {
118	        this.email = email;
119	    }
120	
121	    public LocalDate getRegistrationDate() {
122	        return this.registrationDate;
123	    }
124	
125	    public void setRegistrationDate(LocalDate registrationDate) {
126	        this.registrationDate = registrationDate;
127	    }
128	
129	    public String getCustomerCode() {
130	        return this.customerCode;
131	    }
132	
133	    public void setCustomerCode(String customerCode) {
134	        this.customerCode = customerCode;
135	    }
136	
137	    /**
138	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
139	     * where {@code YY} is the last two digits of the {@link #registrationDate}
140	     * year (e.g. {@code "LON-SMI-0007-M26"}). Derived from the owner's own fields.
141	     */
142	    public String getMembershipNumber() {
143	        if (this.customerCode == null || this.registrationDate == null) {
144	            return null;
145	        }
146	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
147	    }
148	
149	    public String getHouseholdId() {
150	        return this.householdId;
151	    }
152	
153	    public void setHouseholdId(String householdId) {
154	        this.householdId = householdId;
155	    }
156	
157	    /**
158	     * The owner's membership tier, derived from the owner's own fields. Returns
159	     * {@code "SILVER"} when the owner has no namesakes and a contact email on
160	     * file, and {@code "BRONZE"} otherwise.
161	     */
162	    public String getMembershipTier() {
163	        boolean hasEmail = this.email != null && !this.email.isEmpty();
164	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
165	        return (noNamesakes && hasEmail) ? "SILVER" : "BRONZE";
166	    }
167	
168	    public Integer getNamesakeCount() {
169	        return this.namesakeCount;
170	    }
171	
172	    public void setNamesakeCount(Integer namesakeCount) {
173	        this.namesakeCount = namesakeCount;
174	    }
175	
176	    protected Set<Pet> getPetsInternal() {
177	        if (this.pets == null) {
178	            this.pets = new HashSet<>();
179	        }
180	        return this.pets;
181	    }
182	
183	    protected void setPetsInternal(Set<Pet> pets) {
184	        this.pets = pets;
185	    }
186	
187	    public List<Pet> getPets() {
188	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
189	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
190	        return Collections.unmodifiableList(sortedPets);
191	    }
192	
193	    public void setPets(List<Pet> pets) {
194	        this.pets = new HashSet<>(pets);
195	    }
196	
197	    public void addPet(Pet pet) {
198	        getPetsInternal().add(pet);
199	        pet.setOwner(this);
200	    }
201	
202	    /**
203	     * Return the Pet with the given name, or null if none found for this Owner.
204	     *
205	     * @param name to test
206	     * @return true if pet name is already in use
207	     */
208	    public Pet getPet(String name) {
209	        return getPet(name, false);
210	    }
211	
212	    /**
213	     * Return the Pet with the given name, or null if none found for this Owner.
214	     *
215	     * @param name to test
216	     * @return true if pet name is already in use
217	     */
218	    public Pet getPet(String name, boolean ignoreNew) {
219	        name = name.toLowerCase();
220	        for (Pet pet : getPetsInternal()) {
221	            if (!ignoreNew || !pet.isNew()) {
222	                String compName = pet.getName();
223	                compName = compName.toLowerCase();
224	                if (compName.equals(name)) {
225	                    return pet;
226	                }
227	            }
228	        }
229	        return null;
230	    }
231	
232	    public Pet getPet(Integer petId) {
233	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
234	    }
235	
236	    @Override
237	    public String toString() {
238	        return new ToStringCreator(this)
239	
240	            .append("id", this.getId())
241	            .append("new", this.isNew())
242	            .append("lastName", this.getLastName())
243	            .append("firstName", this.getFirstName())
244	            .append("address", this.address)
245	            .append("city", this.city)
246	            .append("telephone", this.telephone)
247	            .append("email", this.email)
248	            .toString();
249	    }
250	}
