16	package org.springframework.samples.petclinic.model;
17	
18	import jakarta.persistence.Column;
19	import jakarta.persistence.MappedSuperclass;
20	
21	import jakarta.validation.constraints.NotEmpty;
22	
23	/**
24	 * Simple JavaBean domain object representing an person.
25	 *
26	 * @author Ken Krebs
27	 */
28	@MappedSuperclass
29	public class Person extends BaseEntity {
30	
31	    @Column(name = "first_name")
32	    @NotEmpty
33	    protected String firstName;
34	
35	    @Column(name = "last_name")
36	    @NotEmpty
37	    protected String lastName;
38	
39	    public String getFirstName() {
40	        return this.firstName;
41	    }
42	
43	    public void setFirstName(String firstName) {
44	        this.firstName = firstName;
45	    }
46	
47	    public String getLastName() {
48	        return this.lastName;
49	    }
50	
51	    public void setLastName(String lastName) {
52	        this.lastName = lastName;
53	    }
54	
55	    /**
56	     * The upper-cased first letters of {@link #firstName} and {@link #lastName},
57	     * dot-separated with a trailing dot (e.g. {@code "J.S."}).
58	     */
59	    public String getInitials() {
60	        return initial(this.firstName) + initial(this.lastName);
61	    }
62	
63	    private static String initial(String name) {
64	        if (name == null || name.isEmpty()) {
65	            return "";
66	        }
67	        return Character.toUpperCase(name.charAt(0)) + ".";
68	    }
69	
70	}
