17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
39	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
40	import org.springframework.samples.petclinic.rest.validation.DuplicateHouseholdException;
41	import org.springframework.samples.petclinic.rest.validation.DuplicateTelephoneException;
42	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
43	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
45	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
46	import org.springframework.samples.petclinic.service.ClinicService;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Maximum number of owners a single city may hold. A create request whose city already contains
66	     * this many owners is rejected as a conflict.
67	     */
68	    static final int MAX_OWNERS_PER_CITY = 50;
69	
70	    private final ClinicService clinicService;
71	
72	    private final OwnerMapper ownerMapper;
73	
74	    private final PetMapper petMapper;
75	
76	    private final VisitMapper visitMapper;
77	
78	    public OwnerRestControllerV1(ClinicService clinicService,
79	                                 OwnerMapper ownerMapper,
80	                                 PetMapper petMapper,
81	                                 VisitMapper visitMapper) {
82	        this.clinicService = clinicService;
83	        this.ownerMapper = ownerMapper;
84	        this.petMapper = petMapper;
85	        this.visitMapper = visitMapper;
86	    }
87	
88	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
89	    @Override
90	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
91	        Collection<Owner> owners;
92	        if (lastName != null) {
93	            owners = this.clinicService.findOwnerByLastName(lastName);
94	        } else {
95	            owners = this.clinicService.findAllOwners();
96	        }
97	        if (owners.isEmpty()) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
106	        Owner owner = this.clinicService.findOwnerById(ownerId);
107	        if (owner == null) {
108	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
109	        }
110	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
117	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
118	        if (!missingFields.isEmpty()) {
119	            throw new MissingOwnerFieldsException(missingFields);
120	        }
121	        HttpHeaders headers = new HttpHeaders();
122	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
123	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
124	            throw new CityCapacityExceededException(owner.getCity());
125	        }
126	        String telephone = TelephoneNormalizer.normalize(owner.getTelephone());
127	        if (!this.clinicService.findOwnerByTelephone(telephone).isEmpty()) {
128	            throw new DuplicateTelephoneException(telephone);
129	        }
130	        Collection<Owner> household =
131	            this.clinicService.findOwnersInHousehold(owner.getLastName(), owner.getAddress());
132	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
133	        if (!household.isEmpty() && !sharesHousehold) {
134	            throw new DuplicateHouseholdException(owner.getLastName(), owner.getAddress());
135	        }
136	        owner.setTelephone(telephone);
137	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
138	        if (sharesHousehold) {
139	            this.clinicService.joinHousehold(owner, household);
140	        }
141	        this.clinicService.saveOwner(owner);
142	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
143	        headers.setLocation(UriComponentsBuilder.newInstance()
144	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
145	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
151	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
152	        if (currentOwner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        currentOwner.setAddress(ownerFieldsDto.getAddress());
156	        currentOwner.setCity(ownerFieldsDto.getCity());
157	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
158	        currentOwner.setLastName(ownerFieldsDto.getLastName());
159	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
160	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
161	        this.clinicService.saveOwner(currentOwner);
162	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Transactional
167	    @Override
168	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        this.clinicService.deleteOwner(owner);
174	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
175	    }
176	
177	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
178	    @Override
179	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
180	        Owner owner = this.clinicService.findOwnerById(ownerId);
181	        if (owner == null) {
182	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
183	        }
184	        HttpHeaders headers = new HttpHeaders();
185	        Pet pet = petMapper.toPet(petFieldsDto);
186	        owner.setId(ownerId);
187	        pet.setOwner(owner);
188	        pet.getType().setName(null);
189	        this.clinicService.savePet(pet);
190	        PetDto petDto = petMapper.toPetDto(pet);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
192	            .buildAndExpand(pet.getId()).toUri());
193	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
194	    }
195	
196	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
197	    @Override
198	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
199	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
200	        if (currentOwner != null) {
201	            Pet currentPet = this.clinicService.findPetById(petId);
202	            if (currentPet != null) {
203	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
204	                currentPet.setName(petFieldsDto.getName());
205	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
206	                this.clinicService.savePet(currentPet);
207	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
208	            }
209	        }
210	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
211	    }
212	
213	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
214	    @Override
215	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
216	        HttpHeaders headers = new HttpHeaders();
217	        Visit visit = visitMapper.toVisit(visitFieldsDto);
218	        Pet pet = new Pet();
219	        pet.setId(petId);
220	        visit.setPet(pet);
221	        this.clinicService.saveVisit(visit);
222	        VisitDto visitDto = visitMapper.toVisitDto(visit);
223	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
224	            .buildAndExpand(visit.getId()).toUri());
225	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
226	    }
227	
228	
229	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
230	    @Override
231	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
232	        Owner owner = this.clinicService.findOwnerById(ownerId);
233	        if (owner != null) {
234	            Pet pet = owner.getPet(petId);
235	            if (pet != null) {
236	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
237	            }
238	        }
239	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	    }
241	}
