18	
19	import java.util.ArrayList;
20	import java.util.LinkedHashMap;
21	import java.util.List;
22	import java.util.Map;
23	import java.util.function.Function;
24	
25	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
26	
27	/**
28	 * Validates that an owner supplies every mandatory field. A field is considered
29	 * missing when it is {@code null} or contains only whitespace.
30	 */
31	public final class OwnerFieldsValidator {
32	
33	    /** The mandatory owner fields, mapped from their JSON name to their accessor. */
34	    private static final Map<String, Function<OwnerFieldsDto, String>> REQUIRED_FIELDS = new LinkedHashMap<>();
35	
36	    static {
37	        REQUIRED_FIELDS.put("firstName", OwnerFieldsDto::getFirstName);
38	        REQUIRED_FIELDS.put("lastName", OwnerFieldsDto::getLastName);
39	        REQUIRED_FIELDS.put("address", OwnerFieldsDto::getAddress);
40	        REQUIRED_FIELDS.put("city", OwnerFieldsDto::getCity);
41	        REQUIRED_FIELDS.put("telephone", OwnerFieldsDto::getTelephone);
42	    }
43	
44	    private OwnerFieldsValidator() {
45	    }
46	
47	    /**
48	     * Returns the names of every mandatory field that is missing or blank, in declaration order.
49	     *
50	     * @param ownerFields the submitted owner fields
51	     * @return the names of the missing fields, or an empty list when all are present
52	     */
53	    public static List<String> findMissingFields(OwnerFieldsDto ownerFields) {
54	        List<String> missing = new ArrayList<>();
55	        REQUIRED_FIELDS.forEach((name, accessor) -> {
56	            String value = accessor.apply(ownerFields);
57	            if (value == null || value.isBlank()) {
58	                missing.add(name);
59	            }
60	        });
61	        return missing;
62	    }
63	}
